getManualStats(token) {
  const key = this.manualStatsKey(token);

  if (!this.manualStatsByUnit.has(key)) {
    this.manualStatsByUnit.set(
      key,
      this.defaultManualStats()
    );
  }

  const fallback = this.manualStatsByUnit.get(key);
  const actor = token?.actor ?? null;
  const system = actor?.system ?? null;

  if (!system) {
    return {
      ...fallback,
      speed: null,
      live: false,
      actorType: null,
      repairsAvailable: true
    };
  }

  const finiteOr = (value, fallbackValue = 0) => {
    const numericValue = Number(value);

    return Number.isFinite(numericValue)
      ? numericValue
      : fallbackValue;
  };

  const rangeValue = (
    range,
    property,
    fallbackValue = 0
  ) => {
    return finiteOr(
      range?.[property],
      fallbackValue
    );
  };

  const repairsAvailable = Boolean(
    system.repairs &&
    typeof system.repairs === "object"
  );

  return {
    hpCurrent: rangeValue(
      system.hp,
      "value",
      fallback.hpCurrent
    ),
    hpMax: rangeValue(
      system.hp,
      "max",
      fallback.hpMax
    ),
    heatCurrent: rangeValue(
      system.heat,
      "value",
      fallback.heatCurrent
    ),
    heatMax: rangeValue(
      system.heat,
      "max",
      fallback.heatMax
    ),
    armor: finiteOr(
      system.armor,
      fallback.armor
    ),
    overshield: rangeValue(
      system.overshield,
      "value",
      fallback.overshield
    ),
    burn: finiteOr(
      system.burn,
