    (!stateTokenId && !stateActorId) ||
    (stateTokenId && stateTokenId === tokenId) ||
    (stateActorId && stateActorId === actorId)
  );

  if (!belongsToCurrentPlan) return;

  if (state.speed !== numericSpeed) {
    state.setSpeed(numericSpeed);
  }
}

